MOD = 998244353

def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    MOD = 998244353

    def mod_inverse(x):
        return pow(x, MOD - 2, MOD)

    inv_n_minus_1 = mod_inverse(n - 1)

    ans = 0
    for i in range(n):
        for j in range(i + 1, n):
            if a[i] > 0 and a[j] > 0:
                term = a[i] * a[j]
                ans = (ans + term) % MOD

    ans = (ans * inv_n_minus_1) % MOD

    return str(ans) + '\n'

if __name__ == "__main__":
    import sys
    print(solution(sys.stdin.read()))
