# filename: solution.py

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:n+1]]

    # Find all rooms using BFS
    visited = [[False] * m for _ in range(n)]
    rooms = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                room = []
                queue = [(i, j)]
                visited[i][j] = True
                while queue:
                    x, y = queue.pop(0)
                    room.append((x, y))
                    for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.' and not visited[nx][ny]:
                            visited[nx][ny] = True
                            queue.append((nx, ny))
                rooms.append(room)

    # For each room, find the bounding box - all cells in bounding box should be free
    # We need to remove walls inside the bounding box to make each room rectangular

    # Create a result grid by finding for each position whether it should be '.' or '*'
    result = [['*' for _ in range(m)] for _ in range(n)]

    # Initially mark all originally free cells as free
    for room in rooms:
        for (x, y) in room:
            result[x][y] = '.'

    # For each room, find its bounding box and fill in any missing free cells (walls that need to be removed)
    for room in rooms:
        min_r, max_r = n, -1
        min_c, max_c = m, -1

        for (x, y) in room:
            min_r = min(min_r, x)
            max_r = max(max_r, x)
            min_c = min(min_c, y)
            max_c = max(max_c, y)

        # Fill the bounding box with free cells (remove walls)
        for x in range(min_r, max_r + 1):
            for y in range(min_c, max_c + 1):
                if grid[x][y] == '*':
                    result[x][y] = '.'

    return '\n'.join(''.join(row) for row in result)
