def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 1:
        return "-1\n"

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i >= len(lines):
            break
        u, v = map(int, lines[i].split())
        if 1 <= u <= n and 1 <= v <= n:
            adj[u].append(v)
            adj[v].append(u)

    # Find connected components using DFS
    visited = [False] * (n + 1)
    component_sizes = []

    def dfs(node):
        stack = [node]
        visited[node] = True
        count = 0
        while stack:
            curr = stack.pop()
            count += 1
            for neighbor in adj[curr]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)
        return count

    for i in range(1, n + 1):
        if not visited[i]:
            component_sizes.append(dfs(i))

    if not component_sizes:
        return "-1\n"

    # Generate lucky numbers up to n
    lucky_numbers = []

    def generate_lucky_numbers(digits):
        if digits > 9:
            digits = 9
        for length in range(1, digits + 1):
            for i in range(4 ** length):
                num = 0
                for pos in range(length):
                    digit = (i >> pos) & 1
                    d = 4 + digit  # 4 or 7
                    num = num * 10 + d
                if num <= n:
                    lucky_numbers.append(num)

    for length in range(1, 11):
        generate_lucky_numbers(length)
    lucky_numbers = sorted(list(set(lucky_numbers)))

    # DP: dp[x] = minimum number of components needed to sum to x
    max_lucky = max(lucky_numbers)
    dp = {}
    dp[0] = 0

    unique_sizes = sorted(set(component_sizes), reverse=True)

    for size in unique_sizes:
        new_dp = dp.copy()
        for original_key, count in dp.items():
            target = original_key + size
            if target <= max_lucky:
                if target not in new_dp or new_dp[target] > count + 1:
                    new_dp[target] = count + 1
        dp = new_dp

    answer = float('inf')
    for lucky in lucky_numbers:
        if lucky in dp and dp[lucky] < answer:
            answer = dp[lucky]

    if answer > component_sizes[0]:  # More than n components, impossible
        return "-1\n"

    return f"{answer-1}\n"


