# Check if a sequence is a geometric progression using rational ratio comparison
def is_geometric(a):
    n = len(a)
    if n <= 2:
        return True

    # If a[0] is 0, all elements must be 0
    if a[0] == 0:
        for x in a:
            if x != 0:
                return False
        return True

    # Use cross-multiplication to avoid floating point issues
    # Check if a[i+1]/a[i] == a[j+1]/a[j] for consecutive pairs
    # i.e., a[i+1] * a[j] == a[j+1] * a[i]

    # Calculate the base ratio using first two elements
    b = a[1]
    c = a[0]

    if c == 0:
        # Already handled above, but safety check
        return False

    # Verify the ratio is consistent for all consecutive elements
    for i in range(1, len(a) - 1):
        if a[i] == 0:
            return False
        # Check a[i+1] / a[i] == b / c
        # Cross multiply: a[i+1] * c == a[i] * b
        if a[i+1] * c != a[i] * b:
            return False

    return True

def check(n, nums):
    # Try removing each element and check if the rest form a GP
    for i in range(n):
        remaining = nums[:i] + nums[i+1:]
        if is_geometric(remaining):
            return True
    return False

