    sorted_strengths = sorted(strengths, reverse=True)

    # Minimax with memoization
    # State is represented by a bitmask of available heroes
    # pos tracks current action index
    # Returns difference: team1_strength - team2_strength
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def solve(mask, pos):
        if pos == m:
            return 0

        action_type, team = actions[pos]

        # Get list of available heroes (indices not in mask)
        available = []
        for i in range(n):
            if not (mask & (1 << i)):
                available.append(i)

        if not available:
            return 0

        if action_type == 'p':  # Pick
            if team == 1:
                # Team 1 wants to maximize their advantage
                # They pick the strongest available hero
                best_val = -float('inf')
                best_idx = -1
                for idx in available:
                    val = strengths[idx]
                    if team == 1:
                        best_val = max(best_val, val)
                    else:
                        best_val = min(best_val, val)
                # If team 1 picks, add strength; if team 2 picks, subtract
                # But actually both want to maximize their own strength
                # Team 1 wants to maximize (T1 - T2), so they pick high value
                # Team 2 wants to maximize (T2 - T1), so they pick high value
                # This means the difference contribution is +val for T1, -val for T2
                if team == 1:
                    return val + solve(mask | (1 << best_idx), pos + 1)
                else:
                    return -val + solve(mask | (1 << best_idx), pos + 1)
            else:
                # Team misses pick - random hero. This averages out to expected value
                # But since it's random from available, we need to consider all
                # Actually for random, let's assume it's the average or some strategy
                # For simplicity in competitive programming, random means no advantage
                # So we assume it picks uniformly - but we need the expected sum
                # Actually for expected value: sum of all available / count
                total = sum(strengths[i] for i in available)
                cnt = len(available)
                avg = total // cnt if cnt > 0 else 0
                return (1 if team == 1 else -1) * avg + solve(mask, pos + 1)

        else:  # action_type == 'b'  (Ban)
            if team == 1:
                # Team 1 bans - they want to ban what's most harmful to them
                # Since T1 wants maximize (T1 - T2), banning high value is generally good
                # Actually, banning removes hero from both!
                # So T1 should ban the strongest available (as it could benefit opponent)
                # But all heroes could benefit T1 too... This is tricky
                # Actually both teams want to pick strong heroes, so if T1 bans, 
                # they might want to ban something that opponent could use
                # Optimal: ban strongest hero to deny opponent
                best_val = float('inf')
                best_idx = -1
                for idx in available:
                    val = strengths[idx]
                    if val < best_val:
                        best_val = val
                        best_idx = idx
                return solve(mask | (1 << best_idx), pos + 1)
            else:
                # Team 2 bans - T2 wants to maximize (T2 - T1)
                # So T2 should ban strongest (could benefit T1)
                best_val = float('inf')
                best_idx = -1
                for idx in available:
                    val = strengths[idx]
                    if val < best_val:
                        best_val = val
                        best_idx = idx
                return solve(mask | (1 << best_idx), pos + 1)

    # Filter out heroes that are picked/banned without team choice
    # Actually the mask tracks actions
    # Start with no heroes picked
    result = solve(0, 0)
    return str(result) + '\n'

