from collections import defaultdict, deque

def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Store pairs (0-based indices)
    pairs = []
    for i in range(m):
        u, v = map(int, lines[2 + i].split())
        pairs.append((u - 1, v - 1))  # Convert to 0-based

    # Function to count occurrences of prime p in number num
    def count_prime(num, p):
        count = 0
        while num > 0 and num % p == 0:
            count += 1
            num //= p
        return count

    # Get all prime factors from all numbers
    all_primes = set()
    for x in a:
        temp = x
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                all_primes.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            all_primes.add(temp)

    total_ops = 0

    # For each prime, compute max flow
    for p in all_primes:
        # Count prime occurrences at each position
        pos_counts = [0] * n
        for i in range(n):
            pos_counts[i] = count_prime(a[i], p)

        # Build flow network
        source = 0
        sink = n + 1
        num_nodes = n + 2

        # Dinic's algorithm implementation
        def build_and_solve():
            # Graph: adjacency list with capacities
            capacity = defaultdict(lambda: defaultdict(int))
            level = {}

            def bfs():
                nonlocal level
                level = {i: -1 for i in range(num_nodes)}
                level[source] = 0
                queue = deque([source])
                while queue:
                    u = queue.popleft()
                    for v in range(num_nodes):
                        if level[v] == -1 and capacity[u][v] > 0:
                            level[v] = level[u] + 1
                            queue.append(v)
                return level[sink] != -1

            def dfs(u, pushed, ptr):
                if pushed == 0 or u == sink:
                    return pushed
                for i in range(ptr[u], num_nodes):
                    v = i
                    if level[v] != level[u] + 1 or capacity[u][v] == 0:
                        continue
                    tr = dfs(v, min(pushed, capacity[u][v]), ptr)
                    if tr == 0:
                        continue
                    capacity[u][v] -= tr
                    capacity[v][u] += tr
                    return tr
                    ptr[u] = i + 1
                return 0

            def dinic():
                flow = 0
                while bfs():
                    ptr = {i: 0 for i in range(num_nodes)}
                    while True:
                        pushed = dfs(source, float('inf'), ptr)
                        if pushed == 0:
                            break
                        flow += pushed
                return flow

            # Build graph
            for i in range(n):
                if pos_counts[i] > 0:
                    # In 0-based: even index = 1-based odd => connects to source
                    # In 0-based: odd index = 1-based even => connects to sink
                    if i % 2 == 0:  # 0-based even (1-based odd)
                        capacity[source][i] = pos_counts[i]
                        capacity[i][source] = 0
                    else:  # 0-based odd (1-based even)
                        capacity[i][sink] = pos_counts[i]
                        capacity[sink][i] = 0

            # Add good pair edges (infinite capacity)
            for u, v in pairs:
                # Only add edge if one position has this prime factor
                if (pos_counts[u] > 0 or pos_counts[v] > 0) and abs(u - v) > 0:
                    # Add bidirectional edges for the pair
                    capacity[u][v] = float('inf')
                    capacity[v][u] = float('inf')

            return dinic()

        total_ops += build_and_solve()

    return str(total_ops) + '\n'


