def solution(input_str):
    lines = input_str.strip().split('\n')
    parts = lines[0].split()
    n, m, k = int(parts[0]), int(parts[1]), int(parts[2])

    # Parse transformers
    transformers = []
    for i in range(1, k + 1):
        p = list(map(int, lines[i].split()))
        x, y, d, t_start, e = p[0], p[1], p[2], p[3], p[4]
        transformers.append((x, y, d, t_start, e))

    # Map each position to a dict: time -> total_energy
    # When reaching position (i,j) at time i+j, we add transformer energy if any are there
    pos_dict = {}  # (i,j) -> {time: total_energy}

    for idx, (x, y, d, t_start, e_cost) in enumerate(transformers):
        # The pattern cycles every 4 steps
        # At time T (>= t_start), compute offset = T - t_start
        # Pattern: (x,y) -> (x+d,y-d) -> (x+d,y) -> (x,y+d) -> repeat
        max_time = n + m - 1  # Maximum possible time at (n-1, m-1)

        for time in range(t_start, max_time + 1):
            offset = time - t_start
            phase = offset % 4

            if phase == 0:
                px, py = x, y
            elif phase == 1:
                px, py = x + d, y - d
            elif phase == 2:
                px, py = x + d, y
            else:  # phase == 3
                px, py = x, y + d

            # Check within bounds (problem guarantees this won't happen for valid inputs)
            if 0 <= px < n and 0 <= py < m:
                if (px, py) not in pos_dict:
                    pos_dict[(px, py)] = {}
                pos_dict[(px, py)][time] = e_cost

    # DP: find minimum energy path from (0,0) to (N-1,M-1)
    INF = float('inf')
    dp = [[INF] * m for _ in range(n)]
    dp[0][0] = 0

    for i in range(n):
        for j in range(m):
            time = i + j  # Time when we reach position (i,j)

            # Get transformer cost at this position and time
            cost = 0
            if (i, j) in pos_dict and time in pos_dict[(i, j)]:
                cost = pos_dict[(i, j)][time]

            # For starting position
            if i == 0 and j == 0:
                # We can only arrive at (0,0) at time 0
                dp[i][j] = 0  # cost is already paid if any transformer is there
            elif i == 0:
                dp[i][j] = dp[i][j-1] + cost
            elif j == 0:
                dp[i][j] = dp[i-1][j] + cost
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + cost

    return str(dp[n-1][m-1])
