        # Option 3: take s1[i] if match
        if i < n and j < m and s1[i] == s2[j]:
            nk = get_next_state(k, s1[i], virus, pi)
            if nk < v:
                cand = 1 + solve_rec(i + 1, j + 1, nk)
                if res < 0 or cand > res:
                    res = cand

        return res if res >= 0 else -float('inf')

    if solve_rec(0, 0, 0) < 0:
        return '0'

    # Reconstruct with parent pointers
    path = []
    i, j, k = 0, 0, 0

    while i < n or j < m and solve_rec(i, j, k) >= 0:
        save_kb = (i, j, k) if solve_rec(i, j, k) >= 0 else None

        best = -float('inf')
        choice = None

        for act in [('skip_s1', i+1, j, k), ('skip_s2', i, j+1, k)]:
            if act[2:] == save_kb:
                rem = solve_rec(*act[2:])
                if rem > best:
                    best = rem
                    choice = act[0]

        # Try take
        if i < n and j < m and s1[i] == s2[j] and k != v:
            nk = get_next_state(k, s1[i], virus, pi)
            if nk < v:
                test = 1 + solve_rec(i+1, j+1, nk)
                if test > best:
                    best = test
                    choice = 'take'

        path.append(choice)
        i, j, k = promote(i, j, k, choice)

        if i >= n and j >= m:
            break

    return ''.join(path[::-1]) if best >= 0 else '0'


def promote(i, j, k, choice):
    if choice == 'skip_s1':
        i += 1
    elif choice == 'skip_s2':
        j += 1
    else:  # take
        i += 1
        j += 1
    return i, j, k
