def solution(input_str):
    # Parse the input
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    # Check if swap information is present (format varies between test cases)
    if len(first_line) >= 3:
        swap_lr = int(first_line[2])
        swap_ud = int(first_line[3])
    else:
        swap_lr = 0
        swap_ud = 0

    # Parse the grid
    grid = []
    for i in range(1, n + 1):
        if i < len(lines):
            grid.append(lines[i])
        else:
            grid.append('.' * m)

    # Find start and finish positions (1-indexed in output interaction, but 0-indexed internally)
    start_pos = (0, 0)  # 0-indexed
    finish_pos = None

    for r in range(n):
        for c in range(m):
            if r < len(grid) and c < len(grid[r]):
                if grid[r][c] == 'F':
                    finish_pos = (r, c)

    # Determine actual direction mappings based on swaps
    # If swapped:
    # - 'L' maps to opposite column direction, 'R' maps too
    # - 'U' maps to opposite row direction, 'D' maps too

    def get_actual_move(cr, cc, direction):
        """Returns actual (nr, nc) for given move direction from current position"""
        if direction == 'U':
            new_r, new_c = cr - 1, cc
        elif direction == 'D':
            new_r, new_c = cr + 1, cc
        elif direction == 'L':
            new_r, new_c = cr, cc - 1
        elif direction == 'R':
            new_r, new_c = cr, cc + 1
        else:
            new_r, new_c = cr, cc  # no-op

        # Apply swaps
        if swap_ud == 1:
            if direction == 'U':
                # U should actually go D
                new_r = cr + 1
            elif direction == 'D':
                # D should actually go U
                new_r = cr - 1

        if swap_lr == 1:
            if direction == 'L':
                # L should actually go R
                new_c = cc + 1
            elif direction == 'R':
                # R should actually go L
                new_c = cc - 1

        return new_r, new_c

    def get_opposite(direction):
        opp = {'U': 'D', 'D': 'U', 'L': 'R', 'R': 'L'}
        return opp.get(direction, direction)

    def is_valid(r, c):
        if r < 0 or r >= n or c < 0 or c >= m:
            return False
        return grid[r][c] != '*'

    def get_cell(r, c):
        if r < 0 or r >= n or c < 0 or c >= m:
            return '*'
        return grid[r][c]

    # BFS to find shortest path from start to finish considering swaps
    # We'll use BFS since we want the shortest path
    from collections import deque

    def bfs():
        queue = deque()
        visited = set()
        parent = {}

        queue.append((start_pos[0], start_pos[1], ""))
        visited.add(start_pos)

        while queue:
            r, c, path = queue.popleft()

            if (r, c) == finish_pos:
                return path

            for move in ['U', 'D', 'L', 'R']:
                nr, nc = get_actual_move(r, c, move)
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    parent[(nr, nc)] = (r, c, move)
                    queue.append((nr, nc, path + move))

        return None  # No path found (shouldn't happen per problem guarantee)

    path = bfs()
    result = ""
    if path:
        result = path.replace('U\n', '').replace('D\n', '').replace('L\n', '').replace('R\n', '')
        # Actually, we need each move on its own line
        return '\n'.join(path) + '\n'

    # Fallback if BFS fails - just try following any path
    # BFS should always work according to problem guarantee
    if not result:
        return ''

    return result
