    n = int(lines[0])

    if n == 0:
        return ""

    edge_data = []
    adj = [[] for _ in range(n + 1)]

    for i in range(1, n):
        v, u = map(int, lines[i].split())
        adj[v].append(u)
        adj[u].append(v)
        edge_data.append((v, u))

    results = []

    # Pre-root at vertex 1
    parent = [0] * (n + 1)
    order = []
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    # For each k from 1 to n
    for k in range(1, n + 1):
        # DFS from leaves up (reverse order)

        # dp[u] = (max_paths, pending_length)
        # pending_length: -1 = None/terminal, 0 = not started, 1 to k-1 = path length in subtree

        def dfs(u):
            # Returns (paths_in_subtree, pending_len_at_u)
            # pending_len_at_u = how many vertices of the path that ends at u from subtree

            child_results = []
            for v in adj[u]:
                if v != parent[u]:
                    cnt, pending = dfs(v)
                    child_results.append((cnt, pending))

            total_paths = sum(cnt for cnt, _ in child_results)

            # Find paths that can be extended or completed at u
            can_extend = []  # (child_index, pending_length)
            can_completed = []  # list, once we complete, we can't extend

            for idx, (cnt, pending) in enumerate(child_results):
                if pending > 0 and pending < k - 1:
                    can_extend.append((idx, pending))
                elif pending == k - 1:
                    can_completed.append(idx)

            # Best pending to extend (longer is better for eventually completing)
            if can_extend:
                best_idx, best_len = max(can_extend, key=lambda x: x[1])
                # After extending, pending becomes best_len + 1
                # If best_len + 1 == k, path completes
                new_pending = best_len + 1

                if new_pending == k:
                    # Path completed, u doesn't carry pending
                    return total_paths + 1, 0
                else:
                    # Path extends, return new pending
                    return total_paths, new_pending
            elif can_completed:
                # Can complete at u (by connecting to zenith) - but we need k-1 from child
                return total_paths + 1, 0
            else:
                # No child has extendable/completable path
                # Try to start a new path at u (length 1)
                return total_paths, 1

        memo = {}

        def dfs_with_memo(u):
            if u in memo:
                return memo[u]

            child_results = []
            for v in adj[u]:
                if v != parent[u]:
                    cnt, pending = dfs_with_memo(v)
                    child_results.append((cnt, pending))

            total_paths = sum(cnt for cnt, _ in child_results)

            can_extend = []
            can_completed = []

            for idx, (cnt, pending) in enumerate(child_results):
                if pending > 0 and pending < k - 1:
                    can_extend.append((idx, pending))
                elif pending == k - 1:
                    can_completed.append(idx)

            if can_extend:
                best_idx, best_len = max(can_extend, key=lambda x: x[1])
                new_pending = best_len + 1

                if new_pending == k:
                    return total_paths + 1, 0
                else:
                    return total_paths, new_pending
            elif can_completed:
                return total_paths + 1, 0
            else:
                return total_paths, 1

        dfs_with_memo(1)
        # Get result from a fresh DFS
        result = [None] * (n + 1)

        def get_result(u):
            if result[u] is not None:
                return result[u]
            child_results = []
            for v in adj[u]:
                if v != parent[u]:
                    cnt, pending = get_result(v)
                    child_results.append((cnt, pending))

            total_paths = sum(cnt for cnt, _ in child_results)

            can_extend = []
            can_completed = []

            for idx, (cnt, pending) in enumerate(child_results):
                if pending > 0 and pending < k - 1:
                    can_extend.append((idx, pending))
                elif pending == k - 1:
                    can_completed.append(idx)

            if can_extend:
                best_idx, best_len = max(can_extend, key=lambda x: x[1])
                new_pending = best_len + 1

                if new_pending == k:
                    result[u] = (total_paths + 1, 0)
                    return result[u]
                else:
                    result[u] = (total_paths, new_pending)
                    return result[u]
            elif can_completed:
                result[u] = (total_paths + 1, 0)
                return result[u]
            else:
                result[u] = (total_paths, 1)
                return result[u]

        cnt, pending = get_result(1)
        results.append(cnt)

    return '\n'.join(map(str, results))
